* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #171b32; color: #f6f2e9; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #30375b 0, #171b32 68%); }
.board { width: min(100%, 520px); padding: 30px; border: 2px solid #596080; border-radius: 18px; background: #222743; box-shadow: 0 12px 0 #11152a, 0 24px 60px #0d1024aa; }
.header { display: flex; align-items: center; gap: 16px; }
.pixel-clock { width: 58px; height: 58px; display: grid; place-items: center; border: 2px solid #f3c969; border-radius: 12px; background: #383d5d; font-size: 30px; }
.eyebrow, .list-heading, footer { color: #aab0cc; font-size: .75rem; font-weight: 800; letter-spacing: .12em; }
.eyebrow { margin: 0 0 4px; color: #f3c969; }
h1 { margin: 0; font-size: clamp(1.45rem, 6vw, 2rem); line-height: 1.2; }
.counter { display: flex; align-items: center; gap: 10px; margin: 24px 0; padding: 14px 16px; border: 1px solid #434a6b; border-radius: 10px; background: #1b2039; color: #d7d9e5; }
.counter-icon { color: #8bd5aa; font-size: .8rem; text-shadow: 0 0 12px #8bd5aa; }
.counter strong { color: #8bd5aa; font-size: 1.2rem; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
legend { margin-bottom: 12px; font-weight: 750; }
.time-fields { display: grid; grid-template-columns: 1fr 18px 1fr; align-items: end; gap: 10px; }
label { display: grid; gap: 7px; color: #d7d9e5; font-size: .9rem; font-weight: 650; }
input { width: 100%; min-height: 48px; padding: 10px 12px; border: 1px solid #596080; border-radius: 8px; outline: none; background: #171b32; color: #f6f2e9; font: inherit; }
input::placeholder { color: #858ba9; }
input:focus-visible, button:focus-visible { outline: 3px solid #f3c969; outline-offset: 3px; }
.colon { padding-bottom: 10px; color: #f3c969; font-size: 1.5rem; text-align: center; }
.label-field { margin-top: 14px; }
.label-field span { color: #aab0cc; font-weight: 400; }
.add-button { width: 100%; min-height: 50px; margin-top: 16px; border: 0; border-radius: 8px; background: #f3c969; color: #222743; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s, background .12s; }
.add-button:hover { background: #ffdc83; }
.add-button:active { transform: translateY(2px); }
.add-button span { margin-right: 5px; font-size: 1.3rem; vertical-align: -1px; }
.alarm-section { margin-top: 28px; }
.list-heading { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding-bottom: 10px; border-bottom: 1px solid #434a6b; }
.list-heading h2 { margin: 0; font-size: .75rem; }
.sorted-note { color: #858ba9; font-size: .65rem; white-space: nowrap; }
.alarm-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.alarm-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #434a6b; border-radius: 10px; background: #292f4c; }
.alarm-info { min-width: 0; }
.alarm-time { display: block; font-size: 1.35rem; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: .04em; }
.alarm-label { display: block; overflow: hidden; color: #aab0cc; font-size: .85rem; text-overflow: ellipsis; white-space: nowrap; }
.toggle-label { display: flex; align-items: center; gap: 7px; color: #d7d9e5; font-size: .82rem; cursor: pointer; }
.toggle-label input { width: 22px; min-height: 22px; height: 22px; margin: 0; accent-color: #8bd5aa; }
.delete-button { min-width: 40px; min-height: 40px; border: 1px solid #596080; border-radius: 8px; background: transparent; color: #f3a8a8; font: inherit; cursor: pointer; }
.delete-button:hover { border-color: #f3a8a8; background: #493449; }
.delete-button:active { transform: scale(.94); }
.alarm-row.is-off .alarm-time { color: #858ba9; }
.alarm-row.is-off { opacity: .72; }
.empty-state { margin: 18px 0; color: #aab0cc; font-size: .9rem; text-align: center; }
footer { margin-top: 28px; text-align: center; font-size: .65rem; }
footer span { color: #f3c969; }
@media (max-width: 420px) { .board { padding: 22px 18px; } .alarm-row { gap: 8px; padding: 11px 9px; } .toggle-label { gap: 5px; font-size: .78rem; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#alarm-label');
const list = document.querySelector('#alarm-list');
const count = document.querySelector('#enabled-count');
const emptyState = document.querySelector('#empty-state');
let nextId = 1;
const alarms = [];

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute) || a.id - b.id);
  list.replaceChildren();
  let enabled = 0;

  for (const alarm of alarms) {
    if (alarm.enabled) enabled += 1;
    const item = document.createElement('li');
    item.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;

    const info = document.createElement('div');
    info.className = 'alarm-info';
    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    info.append(time);
    if (alarm.label) {
      const label = document.createElement('span');
      label.className = 'alarm-label';
      label.textContent = alarm.label;
      info.append(label);
    }

    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle-label';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''} enabled`);
    toggle.addEventListener('change', () => { alarm.enabled = toggle.checked; render(); });
    toggleLabel.append(toggle, document.createTextNode('On'));

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms.splice(alarms.findIndex(entry => entry.id === alarm.id), 1);
      render();
    });

    item.append(info, toggleLabel, remove);
    list.append(item);
  }

  count.textContent = String(enabled);
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.reportValidity()) return;
  alarms.push({
    id: nextId++,
    hour: Number(hourInput.value),
    minute: Number(minuteInput.value),
    label: labelInput.value.trim(),
    enabled: true
  });
  form.reset();
  render();
  hourInput.focus();
});
